-- ---------------------------------------------------------------------------
-- 0029_kristal_menu_products — UP
--
-- Товари, на які вже посилаються сторінки сайту, але яких немає в каталозі:
--   * /kalkulyator            — 11 позицій (норми kristal_calc_norm, Classic і Royal);
--   * /vesilne-meniu, /banketni-stravy, /furshetni-stravy, /kava-breik,
--     /gotuemo                — картки «аддонів» (catering.php);
--   * /vesillya, /furshet, /keiterynh, /korporatyv — картки комплектів (kit.php).
--
-- Зараз ці посилання ведуть на product_id 500xx → 404, а калькулятор показує
-- 0 ₴, бо норми прив'язані до неіснуючих товарів.
--
-- ⚠ ДАНІ-ЗАГЛУШКИ: назви, ціни, залишки й описи взяті з мок-каталогу
--   (db/migrations/0001_mock_catalog.up.sql). Перед запуском на проді
--   замініть ціни, залишки, SKU та фото на реальні. Фото навмисно порожні —
--   тема покаже placeholder.png.
--
-- Міграція ідемпотентна: INSERT ... ON DUPLICATE KEY UPDATE + попередній
-- DELETE для таблиць зв'язків. Відкат — 0029_kristal_menu_products.down.sql.
-- ---------------------------------------------------------------------------

-- 1. Товари (34 шт.)
ON DUPLICATE KEY UPDATE
  `quantity` = VALUES(`quantity`), `price` = VALUES(`price`), `minimum` = VALUES(`minimum`),
  `stock_status_id` = VALUES(`stock_status_id`), `status` = VALUES(`status`),
  `sort_order` = VALUES(`sort_order`), `date_modified` = NOW();

-- 2. Описи (uk-ua)
ON DUPLICATE KEY UPDATE
  `name` = VALUES(`name`), `description` = VALUES(`description`),
  `description_excerpt` = VALUES(`description_excerpt`), `meta_title` = VALUES(`meta_title`),
  `meta_description` = VALUES(`meta_description`), `meta_keyword` = VALUES(`meta_keyword`);

-- 3. Магазин, макет, категорії
DELETE FROM `{{PREFIX}}product_to_store` WHERE `product_id` IN (50001, 50002, 50003, 50005, 50014, 50015, 50018, 50019, 50020, 50021, 50024, 50025, 50027, 50029, 50031, 50033, 50034, 50035, 50037, 50039, 50041, 50043, 50047, 50048, 50050, 50051, 50053, 50056, 50062, 50065, 50066, 50068, 50072, 50086);

DELETE FROM `{{PREFIX}}product_to_layout` WHERE `product_id` IN (50001, 50002, 50003, 50005, 50014, 50015, 50018, 50019, 50020, 50021, 50024, 50025, 50027, 50029, 50031, 50033, 50034, 50035, 50037, 50039, 50041, 50043, 50047, 50048, 50050, 50051, 50053, 50056, 50062, 50065, 50066, 50068, 50072, 50086);

DELETE FROM `{{PREFIX}}product_to_category` WHERE `product_id` IN (50001, 50002, 50003, 50005, 50014, 50015, 50018, 50019, 50020, 50021, 50024, 50025, 50027, 50029, 50031, 50033, 50034, 50035, 50037, 50039, 50041, 50043, 50047, 50048, 50050, 50051, 50053, 50056, 50062, 50065, 50066, 50068, 50072, 50086);

-- 4. Знижки за кількістю (як у кошику)
DELETE FROM `{{PREFIX}}product_discount` WHERE `product_id` IN (50001, 50002, 50003, 50005, 50014, 50015, 50018, 50019, 50020, 50021, 50024, 50025, 50027, 50029, 50031, 50033, 50034, 50035, 50037, 50039, 50041, 50043, 50047, 50048, 50050, 50051, 50053, 50056, 50062, 50065, 50066, 50068, 50072, 50086);

