INSERT INTO `{{PREFIX}}product_description` (`product_id`, `language_id`, `name`, `description`, `description_excerpt`, `description_add`, `tag`, `meta_title`, `meta_description`, `meta_keyword`) VALUES
(50001, 2, 'Тарілка обідня біла 27 см', '<p>Тарілка обідня біла 27 см — для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів. Порцеляна, Ø 27 см, Білий.</p><ul><li>Матеріал: Порцеляна</li><li>Розмір: Ø 27 см</li><li>Колір: Білий</li><li>Серія / стиль: Classic</li></ul><p>Ціна 14 грн — за 1 шт. на добу. Мінімальне замовлення — 20 шт. Відшкодування при бутті або втраті — 120 грн за одиницю.</p>', 'Порцеляна, Ø 27 см, Білий.', 'ціна за 1 шт. на добу', 'оренда, посуд, тарілки', 'Тарілка обідня біла 27 см — оренда у Львові, 14 грн | Крістал', 'Тарілка обідня біла 27 см в оренду: 14 грн (1 шт. на добу), мінімум 20 шт. Доставка по Львову, підбір кількості під вашу подію.', 'оренда'),
(50002, 2, 'Тарілка закусочна біла 21 см', '<p>Тарілка закусочна біла 21 см — для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів. Порцеляна, Ø 21 см, Білий.</p><ul><li>Матеріал: Порцеляна</li><li>Розмір: Ø 21 см</li><li>Колір: Білий</li><li>Серія / стиль: Classic</li></ul><p>Ціна 12 грн — за 1 шт. на добу. Мінімальне замовлення — 20 шт. Відшкодування при бутті або втраті — 100 грн за одиницю.</p>', 'Порцеляна, Ø 21 см, Білий.', 'ціна за 1 шт. на добу', 'оренда, посуд, тарілки', 'Тарілка закусочна біла 21 см — оренда у Львові, 12 грн | Крістал', 'Тарілка закусочна біла 21 см в оренду: 12 грн (1 шт. на добу), мінімум 20 шт. Доставка по Львову, підбір кількості під вашу подію.', 'оренда'),
(50003, 2, 'Тарілка десертна 19 см', '<p>Тарілка десертна 19 см — для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів. Порцеляна, Ø 19 см, Білий.</p><ul><li>Матеріал: Порцеляна</li><li>Розмір: Ø 19 см</li><li>Колір: Білий</li><li>Серія / стиль: Classic</li></ul><p>Ціна 11 грн — за 1 шт. на добу. Мінімальне замовлення — 20 шт. Відшкодування при бутті або втраті — 90 грн за одиницю.</p>', 'Порцеляна, Ø 19 см, Білий.', 'ціна за 1 шт. на добу', 'оренда, посуд, тарілки', 'Тарілка десертна 19 см — оренда у Львові, 11 грн | Крістал', 'Тарілка десертна 19 см в оренду: 11 грн (1 шт. на добу), мінімум 20 шт. Доставка по Львову, підбір кількості під вашу подію.', 'оренда'),
(50005, 2, 'Підставна тарілка золота 33 см', '<p>Підставна тарілка золота 33 см — для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів. Скло з напиленням, Ø 33 см, Золото.</p><ul><li>Матеріал: Скло з напиленням</li><li>Розмір: Ø 33 см</li><li>Колір: Золото</li><li>Серія / стиль: Royal</li></ul><p>Ціна 35 грн — за 1 шт. на добу. Мінімальне замовлення — 10 шт. Відшкодування при бутті або втраті — 350 грн за одиницю.</p>', 'Скло з напиленням, Ø 33 см, Золото.', 'ціна за 1 шт. на добу', 'оренда, посуд, тарілки', 'Підставна тарілка золота 33 см — оренда у Львові, 35 грн | Крістал', 'Підставна тарілка золота 33 см в оренду: 35 грн (1 шт. на добу), мінімум 10 шт. Доставка по Львову, підбір кількості під вашу подію.', 'оренда'),
(50014, 2, 'Етажерка триярусна для десертів', '<p>Етажерка триярусна для десертів — для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів. Метал, порцеляна, висота 38 см, Золото.</p><ul><li>Матеріал: Метал, порцеляна</li><li>Розмір: висота 38 см</li><li>Колір: Золото</li></ul><p>Ціна 90 грн — за 1 шт. на добу. Мінімальне замовлення — 1 шт. Відшкодування при бутті або втраті — 1 200 грн за одиницю.</p>', 'Метал, порцеляна, висота 38 см, Золото.', 'ціна за 1 шт. на добу', 'блюда для подачі, оренда, посуд', 'Етажерка триярусна для десертів — оренда у Львові, 90 грн | Крістал', 'Етажерка триярусна для десертів в оренду: 90 грн (1 шт. на добу), мінімум 10 шт. Доставка по Львову, підбір кількості під вашу подію.', 'оренда'),
(50015, 2, 'Тарілка з золотим обідком 27 см', '<p>Тарілка з золотим обідком 27 см — для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів. Кістяна порцеляна, Ø 27 см, Білий із золотом.</p><ul><li>Матеріал: Кістяна порцеляна</li><li>Розмір: Ø 27 см</li><li>Колір: Білий із золотом</li><li>Серія / стиль: Royal</li></ul><p>Ціна 28 грн — за 1 шт. на добу. Мінімальне замовлення — 10 шт. Відшкодування при бутті або втраті — 400 грн за одиницю.</p>', 'Кістяна порцеляна, Ø 27 см, Білий із золотом.', 'ціна за 1 шт. на добу', 'ексклюзивний посуд, оренда, посуд', 'Тарілка з золотим обідком 27 см — оренда у Львові, 28 грн | Крістал', 'Тарілка з золотим обідком 27 см в оренду: 28 грн (1 шт. на добу), мінімум 10 шт. Доставка по Львову, підбір кількості під вашу подію.', 'оренда'),
(50018, 2, 'Чашка з блюдцем Royal 200 мл', '<p>Чашка з блюдцем Royal 200 мл — для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів. Кістяна порцеляна, 200 мл, Білий із золотом.</p><ul><li>Матеріал: Кістяна порцеляна</li><li>Об\'єм: 200 мл</li><li>Колір: Білий із золотом</li><li>Серія / стиль: Royal</li></ul><p>Ціна 22 грн — за 1 шт. на добу. Мінімальне замовлення — 10 шт. Відшкодування при бутті або втраті — 320 грн за одиницю.</p>', 'Кістяна порцеляна, 200 мл, Білий із золотом.', 'ціна за 1 шт. на добу', 'ексклюзивний посуд, оренда, посуд', 'Чашка з блюдцем Royal 200 мл — оренда у Львові, 22 грн | Крістал', 'Чашка з блюдцем Royal 200 мл в оренду: 22 грн (1 шт. на добу), мінімум 10 шт. Доставка по Львову, підбір кількості під вашу подію.', 'оренда'),
(50019, 2, 'Виделка столова Classic', '<p>Виделка столова Classic — для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів. Нержавіюча сталь, 20 см, Сріблястий.</p><ul><li>Матеріал: Нержавіюча сталь</li><li>Розмір: 20 см</li><li>Колір: Сріблястий</li><li>Серія / стиль: Classic</li></ul><p>Ціна 7 грн — за 1 шт. на добу. Мінімальне замовлення — 20 шт. Відшкодування при бутті або втраті — 60 грн за одиницю.</p>', 'Нержавіюча сталь, 20 см, Сріблястий.', 'ціна за 1 шт. на добу', 'виделки, оренда, столові прибори', 'Виделка столова Classic — оренда у Львові, 7 грн | Крістал', 'Виделка столова Classic в оренду: 7 грн (1 шт. на добу), мінімум 20 шт. Доставка по Львову, підбір кількості під вашу подію.', 'оренда'),
(50020, 2, 'Виделка десертна Classic', '<p>Виделка десертна Classic — для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів. Нержавіюча сталь, 18 см, Сріблястий.</p><ul><li>Матеріал: Нержавіюча сталь</li><li>Розмір: 18 см</li><li>Колір: Сріблястий</li><li>Серія / стиль: Classic</li></ul><p>Ціна 6 грн — за 1 шт. на добу. Мінімальне замовлення — 20 шт. Відшкодування при бутті або втраті — 55 грн за одиницю.</p>', 'Нержавіюча сталь, 18 см, Сріблястий.', 'ціна за 1 шт. на добу', 'виделки, оренда, столові прибори', 'Виделка десертна Classic — оренда у Львові, 6 грн | Крістал', 'Виделка десертна Classic в оренду: 6 грн (1 шт. на добу), мінімум 20 шт. Доставка по Львову, підбір кількості під вашу подію.', 'оренда'),
(50021, 2, 'Виделка столова золота Royal', '<p>Виделка столова золота Royal — для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів. Сталь, PVD-покриття, 21 см, Золото.</p><ul><li>Матеріал: Сталь, PVD-покриття</li><li>Розмір: 21 см</li><li>Колір: Золото</li><li>Серія / стиль: Royal</li></ul><p>Ціна 12 грн — за 1 шт. на добу. Мінімальне замовлення — 20 шт. Відшкодування при бутті або втраті — 150 грн за одиницю.</p>', 'Сталь, PVD-покриття, 21 см, Золото.', 'ціна за 1 шт. на добу', 'виделки, оренда, столові прибори', 'Виделка столова золота Royal — оренда у Львові, 12 грн | Крістал', 'Виделка столова золота Royal в оренду: 12 грн (1 шт. на добу), мінімум 20 шт. Доставка по Львову, підбір кількості під вашу подію.', 'оренда'),
(50024, 2, 'Ложка чайна Classic', '<p>Ложка чайна Classic — для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів. Нержавіюча сталь, 14 см, Сріблястий.</p><ul><li>Матеріал: Нержавіюча сталь</li><li>Розмір: 14 см</li><li>Колір: Сріблястий</li><li>Серія / стиль: Classic</li></ul><p>Ціна 5 грн — за 1 шт. на добу. Мінімальне замовлення — 20 шт. Відшкодування при бутті або втраті — 45 грн за одиницю.</p>', 'Нержавіюча сталь, 14 см, Сріблястий.', 'ціна за 1 шт. на добу', 'ложки, оренда, столові прибори', 'Ложка чайна Classic — оренда у Львові, 5 грн | Крістал', 'Ложка чайна Classic в оренду: 5 грн (1 шт. на добу), мінімум 20 шт. Доставка по Львову, підбір кількості під вашу подію.', 'оренда'),
(50025, 2, 'Ложка десертна золота Royal', '<p>Ложка десертна золота Royal — для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів. Сталь, PVD-покриття, 18 см, Золото.</p><ul><li>Матеріал: Сталь, PVD-покриття</li><li>Розмір: 18 см</li><li>Колір: Золото</li><li>Серія / стиль: Royal</li></ul><p>Ціна 11 грн — за 1 шт. на добу. Мінімальне замовлення — 20 шт. Відшкодування при бутті або втраті — 140 грн за одиницю.</p>', 'Сталь, PVD-покриття, 18 см, Золото.', 'ціна за 1 шт. на добу', 'ложки, оренда, столові прибори', 'Ложка десертна золота Royal — оренда у Львові, 11 грн | Крістал', 'Ложка десертна золота Royal в оренду: 11 грн (1 шт. на добу), мінімум 20 шт. Доставка по Львову, підбір кількості під вашу подію.', 'оренда'),
